import logging
from functools import wraps
import time
def retry(max_attempts: int = 3, delay: float = 1.0, backoff: float = 2.0):
 """Decorator: retry failed I/O operations with exponential backoff."""
 def decorator(func):
 @wraps(func)
 def wrapper(*args, **kwargs):
 attempt = 0
 current_delay = delay
 while attempt < max_attempts:
 try:
 return func(*args, **kwargs)
 except Exception as e:
 attempt += 1
 if attempt == max_attempts:
 logging.error(f"{func.__name__} failed after {max_attempts} 
attempts: {e}")
 raise
 logging.warning(f"{func.__name__} attempt {attempt} failed: 
{e}. Retrying in {current_delay}s")
 time.sleep(current_delay)
 current_delay *= backoff
 return wrapper
 return decorator
